import {yearLabel} from './catalog.mjs';
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeImage = value => { try { const url = new URL(value); return url.protocol === 'https:' && !url.username && !url.password ? value : ''; } catch { return ''; } };
export function renderJourney(journey,grade,{base=''} = {}) {
  const year = yearLabel(grade);
  const heading = `<header class="journey-heading year-${grade}"><p>Learning Journey${journey ? ` · ${journey.academicYear}` : ''}</p><h1>${year} Mandarin adventure</h1><p>Take your next step, revisit a favourite, or explore something new.</p></header>`;
  const timeline = !journey ? '<p class="empty-state">Your Learning Journey is coming soon. Explore more Mandarin below while your teacher prepares it.</p>' : !journey.slots.length ? '<p class="empty-state">Your next steps are coming soon.</p>' : `<ol class="journey-timeline">${journey.slots.map(slot => {
    if (slot.status === 'upcoming') return '<li class="journey-stop upcoming"><span class="journey-marker" aria-hidden="true">🔒</span><article class="journey-card"><p class="journey-status">Upcoming</p><h2>Coming Soon</h2><p>A new adventure is on its way.</p></article></li>';
    const unit = journey.units.get(slot.unitId), current = slot.status === 'current';
    if (!unit) return `<li class="journey-stop"><span class="journey-marker" aria-hidden="true">${current?'★':'✓'}</span><article class="journey-card"><p class="journey-status">${current?'Current':'Completed'}</p><h2>Unit unavailable</h2><p>This Unit is not currently available. Please check with your teacher.</p></article></li>`;
    const image = current ? safeImage(unit.lessons.flatMap(lesson => lesson.workedExamples || [])[0]?.url) : '';
    return `<li class="journey-stop ${current?'current':'completed'}"><span class="journey-marker" aria-hidden="true">${current?'★':'✓'}</span><article class="journey-card ${current?'year-'+grade:''}"><div class="journey-copy"><p class="journey-status">${current?'Current · Your next adventure':'Completed'}</p><h2>${esc(unit.englishTitle)}</h2>${unit.chineseTitle?`<p lang="zh-Hans">${esc(unit.chineseTitle)}</p>`:''}${unit.description?`<p>${esc(unit.description)}</p>`:''}<a class="button ${current?'':'secondary'}" href="${base}#/unit?unit=${encodeURIComponent(slot.unitId)}">${current?'Continue Learning':'Review'} <span aria-hidden="true">→</span></a></div>${current?`<img class="journey-cover" src="${esc(image || 'assets/emblem.svg')}" alt="${image?'Approved illustration for '+esc(unit.englishTitle):'The Mandarin Room emblem'}" loading="lazy" referrerpolicy="no-referrer">`:''}</article></li>`;
  }).join('')}</ol>`;
  return `<section class="learning-journey"><a class="back-link" href="${base}#/">← Choose your year level</a>${heading}${timeline}<aside class="journey-explore"><h2>Finished Early? Choose your own Mandarin adventure!</h2><div><a class="button secondary" href="${base}#/vocabulary?year=${grade}">Explore Words →</a><a class="button secondary" href="${base}#/topics">Explore Topics →</a><a class="button secondary" href="${base}#/activities">Play &amp; Practise →</a></div></aside></section>`;
}
